      errorNode.textContent = '';
    }

    function validateFullName() {
      const value = fields.fullName.value.trim();
      if (!value) {
        setError(fields.fullName, errors.fullName, 'Full name is required.');
        return false;
      }
      clearError(fields.fullName, errors.fullName);
      return true;
    }

    function validateEmail() {
      const value = fields.email.value.trim();
      if (!value) {
        setError(fields.email, errors.email, 'Email address is required.');
        return false;
      }

      if (!fields.email.checkValidity()) {
        setError(fields.email, errors.email, 'Enter a valid email address.');
        return false;
      }

      clearError(fields.email, errors.email);
      return true;
    }

    function validatePhone() {
      const value = fields.phone.value.trim();
      if (!value) {
        clearError(fields.phone, errors.phone);
        return true;
      }

      const phonePattern = /^[+]?[\d\s().-]{7,}$/;
      if (!phonePattern.test(value)) {
        setError(fields.phone, errors.phone, 'Enter a valid phone number or leave it blank.');
        return false;
      }

      clearError(fields.phone, errors.phone);
      return true;
    }

    function validateField(name) {
      if (name === 'fullName') return validateFullName();
      if (name === 'email') return validateEmail();
      return validatePhone();
    }

