 </head>
 <body>
   <main class="page-shell">
     <section class="hero" aria-labelledby="support-title">
       <span class="eyebrow">Support</span>
       <h1 id="support-title">Contact our team</h1>
       <p class="subtitle">Send us a note and we’ll get back to you as soon as possible.</p>
     </section>

     <section class="card" aria-label="Support contact form">
       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="fullName">Full name</label>
           <input id="fullName" name="fullName" type="text" autocomplete="name" placeholder="Jane Doe" required />
           <div class="error-message" id="fullName-error" aria-live="polite"></div>
         </div>

         <div class="form-field">
           <label for="email">Email address</label>
           <input id="email" name="email" type="email" autocomplete="email" placeholder="jane@example.com" required />
           <div class="error-message" id="email-error" aria-live="polite"></div>
         </div>

         <div class="form-field">
           <label for="phone">Phone number</label>
           <input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="+1 (555) 123-4567" inputmode="tel" />
           <div class="helper-text">Optional. Use a number like +1 (555) 123-4567.</div>
           <div class="error-message" id="phone-error" aria-live="polite"></div>
         </div>

         <div class="actions">
           <button type="submit">Send message</button>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const fields = {
       fullName: document.getElementById('fullName'),
       email: document.getElementById('email'),
       phone: document.getElementById('phone')
     };
     const errors = {
       fullName: document.getElementById('fullName-error'),
       email: document.getElementById('email-error'),
       phone: document.getElementById('phone-error')
     };

     function setError(input, errorNode, message) {
       input.setAttribute('aria-invalid', 'true');
       errorNode.textContent = message;
     }

     function clearError(input, errorNode) {
       input.removeAttribute('aria-invalid');
       errorNode.textContent = '';
     }

     function validateFullName() {
       const value = fields.fullName.value.trim();
       if (!value) {
         setError(fields.fullName, errors.fullName, 'Full name is required.');
         return false;
       }
       clearError(fields.fullName, errors.fullName);
       return true;
     }

     function validateEmail() {
       const value = fields.email.value.trim();
       if (!value) {
         setError(fields.email, errors.email, 'Email address is required.');
         return false;
       }

       if (!fields.email.checkValidity()) {
         setError(fields.email, errors.email, 'Enter a valid email address.');
         return false;
       }

       clearError(fields.email, errors.email);
       return true;
     }

     function validatePhone() {
       const value = fields.phone.value.trim();
       if (!value) {
         clearError(fields.phone, errors.phone);
         return true;
       }

       const phonePattern = /^[+]?[\d\s().-]{7,}$/;
       if (!phonePattern.test(value)) {
         setError(fields.phone, errors.phone, 'Enter a valid phone number or leave it blank.');
         return false;
       }

       clearError(fields.phone, errors.phone);
       return true;
     }

     function validateField(name) {
       if (name === 'fullName') return validateFullName();
       if (name === 'email') return validateEmail();
       return validatePhone();
     }

     Object.keys(fields).forEach((name) => {
       const field = fields[name];
       field.addEventListener('blur', () => validateField(name));
       field.addEventListener('input', () => {
         if (field.getAttribute('aria-invalid') === 'true') {
           validateField(name);
         }
       });
     });

     form.addEventListener('submit', (event) => {
       const isValid = [validateFullName(), validateEmail(), validatePhone()].every(Boolean);
       if (!isValid) {
         event.preventDefault();
         return;
       }

       event.preventDefault();
       form.reset();
       Object.entries(fields).forEach(([name, input]) => clearError(input, errors[name]));
     });
   </script>
 </body>
